import{_ as t,l as s,o as e,c as l,v as o,p as c,x as i,d as n,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const v=JSON.parse('{"title":"VFIO","description":"","frontmatter":{"title":"VFIO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vfio.md","filePath":"cs/vfio.md","lastUpdated":1789023840000}'),h={name:"cs/vfio.md"};function M(m,a,f,u,I,_){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="vfio" tabindex="-1">VFIO <a class="header-anchor" href="#vfio" aria-label="Permalink to &quot;VFIO&quot;">​</a></h1><div class="epigraph"><p>VFIO 把 IOMMU 组交给用户进程：QEMU mmap 设备 BAR、映射客户内存给 DMA，实现安全设备直通。</p><footer>—— 据 Linux vfio 文档；[DMA/IOMMU](/cs/dma-coherence) 与 [DPDK](/cs/dpdk-kernel-bypass) 为先修</footer></div><p><a href="/cs/sriov-passthrough">SR-IOV</a> 要有框架绑设备。<a href="/cs/chardev-ioctl">ioctl</a> 再出现：<code>/dev/vfio</code>。缺口是 <strong>VFIO</strong>：组、容器、与设备隔离。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IOMMU 组必须整组给一个用户，否则 DMA 别名。VFIO：用户拿组 → 设 DMA map → mmap MMIO。缺口：no-IOMMU 模式危险；与 <a href="/cs/secure-boot">secure boot</a> 模块签名。本课不把每个 PCI quirk 列出。</p><p><span class="marginnote">vfio-pci 替换宿主驱动。对象是安全用户 DMA，不仅是虚拟化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解绑宿主驱动 → 绑 vfio-pci → QEMU 打开组 → 运行。对照 DPDK：同一 VFIO，用途旁路而非客户。对照 <a href="/cs/chardev-ioctl">chardev</a>：vfio 就是一类 cdev。对照 KSM：客户页仍可被宿主合并，直通 DMA 要钉页。</p>',8)),(e(),c(d,null,{default:i(()=>[p(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GRP%5B%22IOMMU%20%E7%BB%84%22%5D%20--%3E%20U%5B%22%E7%94%A8%E6%88%B7%20VFIO%22%5D%0A%20%20U%20--%3E%20MAP%5B%22DMA%20%E6%98%A0%E5%B0%84%E5%AE%A2%E6%88%B7%E5%86%85%E5%AD%98%22%5D%0A%20%20U%20--%3E%20BAR%5B%22mmap%20%E8%AE%BE%E5%A4%87%20BAR%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>VFIO 把「设备用户态驱动」做成有 IOMMU 的一等公民，KVM 直通与 DPDK 共用。没有组隔离就没有安全直通。不要写成驱动编写教程。与 <a href="/cs/memcg">memcg</a>：钉页会计。</p><p>错误映射等于客户写宿主。</p><p>实现上：组内任一设备给客户，组内其它也必须解绑宿主驱动。no-iommu 模式等于信任用户 DMA 整机。mmap BAR 后客户 MMIO 不再 exit。 读法上只引用<a href="/cs/sriov-passthrough">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>VFIO</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 mdev/vGPU 的全部。不保证所有桥接芯片组可拆组。下一课中断虚拟化。</p><p>版本字段会变，课序钉的是机制对象「VFIO」，不是某一主线内核的结构体名。 后课默认：直通经 VFIO+IOMMU 组。客户中断如何少 exit，下一课 posted interrupt。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VFIO 将 IOMMU 组授予用户做 DMA/MMIO。</li><li>是 KVM 直通与用户态驱动的共同底座。</li><li>中断虚拟化是下一课。</li><li>出处：Linux vfio；IOMMU；KVM。</li></ul>',11))])}const O=t(h,[["render",M]]);export{v as __pageData,O as default};
